insert into candidate_positions (id, candidate_id, question_id, score, explanation, source_url) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:position:pos-jean-luc-melenchon-q1-0'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:jean-luc-melenchon'), uuid_generate_v5(uuid_ns_url(), 'poliscope:question:q1'), -2, 'Propose d''abroger la réforme de 2023 et de revenir à un départ à 60 ans.', 'https://melenchon2027.fr/programme2025/livre/chapitre8/s8/') on conflict (id) do nothing;
insert into candidate_positions (id, candidate_id, question_id, score, explanation, source_url) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:position:pos-jean-luc-melenchon-q2-1'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:jean-luc-melenchon'), uuid_generate_v5(uuid_ns_url(), 'poliscope:question:q2'), 2, 'Propose un départ à 60 ans pour toute carrière complète, avec prise en compte de la pénibilité.', 'https://melenchon2027.fr/programme2025/livre/chapitre8/s8/') on conflict (id) do nothing;
insert into candidate_positions (id, candidate_id, question_id, score, explanation, source_url) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:position:pos-jean-luc-melenchon-q3-2'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:jean-luc-melenchon'), uuid_generate_v5(uuid_ns_url(), 'poliscope:question:q3'), -2, 'Son programme d''« urgence sociale » prévoit une hausse des dépenses sociales, pas une baisse de la dépense publique.', 'https://melenchon2027.fr/programme2025/livre/chapitre9/s1/') on conflict (id) do nothing;
