insert into candidate_positions (id, candidate_id, question_id, score, explanation, source_url) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:position:pos-jean-luc-melenchon-q6-4'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:jean-luc-melenchon'), uuid_generate_v5(uuid_ns_url(), 'poliscope:question:q6'), -2, 'Son programme migratoire vise à faciliter l''accès aux visas et à suspendre le règlement de Dublin, pas à réduire l''immigration légale.', 'https://melenchon2027.fr/programme2025/livre/chapitre16/s7/') on conflict (id) do nothing;
